// mapper: one direction per function; the domain object stays plain
export const toCustomer = (row) => new Customer({ id: row.id, name: row.name });

export async function findCustomer(pool, id) {
  const { rows } = await pool.query("SELECT id, name FROM customers WHERE id = $1", [id]);
  return rows.length ? toCustomer(rows[0]) : null;
}

export async function saveCustomer(client, c) {   // client, not pool: the write stays in the transaction
  await client.query("UPDATE customers SET name = $1 WHERE id = $2", [c.name, c.id]);
}
